using System.ComponentModel;
using Avalonia.Controls;
using Crustcut.Presentation;

namespace Crustcut.App;

public partial class MainWindow : Window
{
    private readonly ShellViewModel _shell;
    private readonly PageFactory _pages;

    public MainWindow() : this(new ShellViewModel(), null) { }

    public MainWindow(ShellViewModel shell, Composition? app)
    {
        // InitializeComponent is generated by the Avalonia XAML compiler; it also assigns
        // the x:Name fields (PageHost). Declaring it by hand shadows that and leaves the
        // fields null.
        InitializeComponent();

        _shell = shell;
        _pages = new PageFactory(app);
        DataContext = shell;

        var v = System.Reflection.Assembly.GetEntryAssembly()?.GetName().Version;
        VersionLabel.Text = v is null ? "" : $"v{v.ToString(3)}";

        // Avalonia 12: ExtendClientAreaToDecorationsHint alone removes the stock caption
        // bar (the old ChromeHints enum is gone from the API); our title strip supplies
        // the minimize/close buttons.

        _shell.PropertyChanged += OnShellPropertyChanged;
        ShowActivePage();
    }

    private void OnShellPropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (e.PropertyName == nameof(ShellViewModel.ActiveTab)) ShowActivePage();
    }

    // ── Custom chrome ────────────────────────────────────────────────────────────────
    private void TitleBarPressed(object? sender, Avalonia.Input.PointerPressedEventArgs e)
    {
        if (!e.GetCurrentPoint(this).Properties.IsLeftButtonPressed) return;
        if (e.ClickCount == 2)
        {
            WindowState = WindowState == WindowState.Maximized
                ? WindowState.Normal : WindowState.Maximized;
            return;
        }
        BeginMoveDrag(e);
    }

    private void MinimizeClick(object? sender, Avalonia.Interactivity.RoutedEventArgs e)
        => WindowState = WindowState.Minimized;

    // Close(), not Shutdown: the Closing handler owns the minimise-to-tray decision, and
    // our X must behave exactly like the one Windows used to draw.
    private void CloseClick(object? sender, Avalonia.Interactivity.RoutedEventArgs e)
        => Close();

    private void ResizePressed(object? sender, Avalonia.Input.PointerPressedEventArgs e)
    {
        if (WindowState != WindowState.Normal) return;   // no resizing a maximized window
        if (sender is not Border b) return;
        var edge = b.Name switch
        {
            "ResizeN" => WindowEdge.North,
            "ResizeS" => WindowEdge.South,
            "ResizeW" => WindowEdge.West,
            "ResizeE" => WindowEdge.East,
            "ResizeNW" => WindowEdge.NorthWest,
            "ResizeNE" => WindowEdge.NorthEast,
            "ResizeSW" => WindowEdge.SouthWest,
            _ => WindowEdge.SouthEast,
        };
        BeginResizeDrag(edge, e);
    }

    protected override void OnOpened(EventArgs e)
    {
        base.OnOpened(e);
        // A borderless window loses Windows 11's rounded corners; DWM gives them back.
        try
        {
            var handle = TryGetPlatformHandle()?.Handle;
            if (handle is IntPtr h && h != IntPtr.Zero)
            {
                const int DWMWA_WINDOW_CORNER_PREFERENCE = 33;
                var pref = 2; // DWMWCP_ROUND
                _ = DwmSetWindowAttribute(h, DWMWA_WINDOW_CORNER_PREFERENCE, ref pref, sizeof(int));
            }
        }
        catch { /* pre-Win11: square corners, which suit the app anyway */ }
    }

    [System.Runtime.InteropServices.DllImport("dwmapi.dll")]
    private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);

    private void ShowActivePage() => PageHost.Content = _pages.Create(_shell.ActiveTab);

    /// <summary>Switches tab programmatically. Used by the --screenshot debug flag.</summary>
    public void NavigateTo(string tabId) => _shell.NavigateCommand.Execute(tabId);

    private Crustcut.Presentation.UpdateViewModel? _updates;

    /// <summary>
    /// Wires the update banner. Kept out of XAML bindings on purpose: the banner lives in
    /// the shell chrome, which has the ShellViewModel as its DataContext.
    /// </summary>
    public void AttachUpdates(Crustcut.Presentation.UpdateViewModel updates)
    {
        _updates = updates;
        updates.PropertyChanged += (_, e) =>
        {
            if (e.PropertyName is nameof(updates.UpdateAvailable) or nameof(updates.Headline))
            {
                UpdateBanner.IsVisible = updates.UpdateAvailable;
                UpdateHeadline.Text = updates.Headline;
            }
            if (e.PropertyName is nameof(updates.Status) or nameof(updates.IsBusy))
            {
                UpdateStatus.Text = updates.Status;
                UpdateStatus.IsVisible = !string.IsNullOrEmpty(updates.Status);
                UpdateNowButton.IsEnabled = !updates.IsBusy;
            }
        };
    }

    private async void UpdateNowClick(object? sender, Avalonia.Interactivity.RoutedEventArgs e)
    {
        if (_updates is not null) await _updates.UpdateNowAsync();
    }

    private void UpdateLaterClick(object? sender, Avalonia.Interactivity.RoutedEventArgs e)
        => UpdateBanner.IsVisible = false;
}
